{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Dexetimide is reported to have good brain penetration and desirable properties for PET neuroreceptor imaging, directly supporting meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "In mice, the radioligand [18F]3 showed a brain-to-blood ratio that increased to 6.3, indicating ready passage across the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "In female CD-1 mice, [18F]3 showed fast and significant brain uptake of 2.20% injected dose per gram within 5 minutes, confirming meaningful brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "The sigma-1 receptor radiotracer [18F]-(R)-20 achieved 3.4% injected dose per gram in brain and labeled receptor-rich regions, demonstrating adequate CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Compound 27 was detected in mouse brain at 10-20% of blood concentration after both administration routes, indicating measurable BBB passage and brain accumulation.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Planar imaging in monkeys showed significant accumulation of the iodobenzamide radiotracer in the brain, supporting CNS penetration for this chemical class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple independent in vivo brain-uptake and imaging records from related CNS radiotracers and receptor ligands consistently demonstrate meaningful BBB penetration. The physicochemical prior also favors passive BBB permeation, and no contradictory experimental evidence was identified.",
  "evidence_gaps": [
    "No direct experimental brain or CSF measurement for the query molecule itself.",
    "Unbound brain-to-plasma ratio and functional CNS exposure are not directly quantified.",
    "Efflux transporter substrate status is inferred rather than directly measured.",
    "One record (C06) shows a lower brain-to-blood ratio, but it still indicates measurable brain accumulation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

